// Outside watchdog for the monitoring stack. Grafana can't alert about itself, so n8n
// (RPi4, separate hardware) probes it. 2 misses in a row (~10 min) = DOWN; one message on
// down, one on recovery, a reminder every ~6 h while still down. State lives in workflow
// static data, which only persists for ACTIVE (scheduled) runs, not manual test runs.
const sd = $getWorkflowStaticData('global');
sd.svc = sd.svc || {};
const STRIKES = 2;
const REMIND_EVERY = 72; // runs (5 min each) = 6 h

const checks = [
  { key: 'grafana', name: 'Grafana (CT405)', node: 'Grafana health',
    ok: r => r.statusCode === 200 && /"database"\s*:\s*"ok"/.test(String(r.body)) },
  { key: 'victoriametrics', name: 'VictoriaMetrics (CT405)', node: 'VictoriaMetrics health',
    ok: r => r.statusCode === 200 },
  // Loki's /ready can sit at 503 ("waiting for 15s after being ready") while it is working
  // fine, so probe a real label query instead.
  { key: 'loki', name: 'Loki (CT405)', node: 'Loki query',
    ok: r => r.statusCode === 200 && /"status"\s*:\s*"success"/.test(String(r.body)) },
  { key: 'gotify', name: 'Gotify (CT203)', node: 'Gotify health',
    ok: r => r.statusCode === 200 && /"health"\s*:\s*"green"/.test(String(r.body)) },
];

const fmt = iso => new Date(iso).toLocaleString('en-US', { timeZone: 'America/Chicago', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
const now = new Date().toISOString();
const down = [], back = [], still = [];
const healthy = {};

for (const c of checks) {
  let r = {};
  try { r = $(c.node).first().json || {}; } catch (e) { r = { error: { message: 'no output' } }; }
  const ok = !r.error && c.ok(r);
  healthy[c.key] = ok;
  const s = sd.svc[c.key] || { fails: 0, down: false, since: null };
  if (ok) {
    if (s.down) back.push(`✓ ${c.name} is back (down since ${fmt(s.since)})`);
    sd.svc[c.key] = { fails: 0, down: false, since: null };
    continue;
  }
  s.fails += 1;
  const why = r.error ? (r.error.message || r.error.code || 'request failed') : `HTTP ${r.statusCode}`;
  if (!s.down && s.fails >= STRIKES) {
    s.down = true; s.since = now;
    down.push(`• ${c.name}: ${why}`);
  } else if (s.down && (s.fails - STRIKES) % REMIND_EVERY === 0) {
    still.push(`• ${c.name} still down since ${fmt(s.since)}: ${why}`);
  }
  sd.svc[c.key] = s;
}

if (!down.length && !back.length && !still.length) return [];

const anyDown = down.length || still.length;
const title = down.length ? `[DOWN] Monitoring watchdog: ${down.map(l => l.split(':')[0].slice(2)).join(', ')}`
  : still.length ? '[STILL DOWN] Monitoring watchdog'
  : '[RESOLVED] Monitoring watchdog';
const lines = [...down, ...still, ...back];
if (anyDown) {
  lines.push('');
  lines.push('While this lasts, Grafana alerts may not be delivered.');
  if (!healthy.grafana || !healthy.victoriametrics || !healthy.loki)
    lines.push("Check CT405: ssh evox2 'pct exec 405 -- docker ps -a' (then docker compose logs <svc> in /root/Homelab-ops/infrastructure/observability-lxc).");
  if (!healthy.gotify)
    lines.push("Check CT203: ssh peladn 'pct exec 203 -- docker ps -a' (gotify) and the NPM proxy for notifications.");
}
lines.push('', '(from the n8n watchdog on the RPi4)');

return [{ json: { title, message: lines.join('\n'), priority: anyDown ? 8 : 4, gotifyUp: healthy.gotify } }];
